const cache = new Map();
function load(path) {
  path=pathUtils.resolve(path);
  if(cache.has(path)) return cache.get(path);
  const module = {exports:{}}; cache.set(path,module.exports);
  const source=ts.transpileModule(fs.readFileSync(path,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}).outputText;
  new Function('require','module','exports',source)(name=>name==='obsidian'?{normalizePath:p=>p,TFile:MockFile,TFolder:MockFolder,Notice:class {},Events:class {}}:name.startsWith('.')?load(pathUtils.resolve(pathUtils.dirname(path),name+'.ts')):nativeRequire(name),module,module.exports);
  return module.exports;
}
